struct VSOut {
    float4 pos : SV_POSITION;
    [[vk::location(0)]] float2 uv : TEXCOORD0;
};

VSOut VSMain(uint vid : SV_VertexID)
{
    VSOut o;
    o.uv = float2((vid << 1) & 2, vid & 2);
    o.pos = float4(o.uv * 2.0f - 1.0f, 0.0f, 1.0f);
    o.uv.y = 1.0f - o.uv.y;
    return o;
}

cbuffer Host : register(b0)
{
    float time_sim_ms;
    float time_wall_ms;
    float delta_time_ms;
    uint  frame_index;
    float resolution_x;
    float resolution_y;
    float mouse_x;
    float mouse_y;
    uint  mouse_buttons;
    float scroll_delta_x;
    float scroll_delta_y;
    float drag_accum_x;
    float drag_accum_y;
    float scroll_accum_x;
    float scroll_accum_y;
    float pan_accum_x;
    float pan_accum_y;
};

struct VSOut {
    float4 pos : SV_POSITION;
    [[vk::location(0)]] float2 uv : TEXCOORD0;
};

float4 PSMain(VSOut i) : SV_Target
{
    float t = time_sim_ms * 0.001;
    float2 uv = i.uv * 2.0 - 1.0;
    float aspect = resolution_x / max(1.0, resolution_y);
    uv.x *= aspect;
    float freq = 40.0;
    float2 c1 = float2(sin(t * 0.5) * 0.3, cos(t * 0.3) * 0.3);
    float2 c2 = float2(cos(t * 0.4) * 0.3, sin(t * 0.6) * 0.3);
    float d1 = length(uv - c1);
    float d2 = length(uv - c2);
    float rings1 = 0.5 + 0.5 * sin(d1 * freq);
    float rings2 = 0.5 + 0.5 * sin(d2 * freq);
    float moire = rings1 * rings2;
    float3 col = float3(moire, moire * 0.8, moire * 0.6);
    col = lerp(col, float3(0.1, 0.2, 0.5), 1.0 - moire);
    return float4(col, 1.0);
}
